begin;
create schema admin_domain_test;
create function admin_domain_test.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'ok - admin domain: %',label;end$$;
create function admin_domain_test.fails(command text,label text) returns void language plpgsql as $$begin begin execute command;exception when others then raise notice 'ok - admin domain: % (refused)',label;return;end;raise exception 'FAIL: % was permitted',label;end$$;
grant usage on schema admin_domain_test to authenticated,service_role;
grant execute on all functions in schema admin_domain_test to authenticated,service_role;
insert into auth.users(id,email) values
 ('de000000-0000-4000-8000-000000000001','admin-domain-owner@example.test'),
 ('de000000-0000-4000-8000-000000000002','admin-domain-admin@example.test'),
 ('de000000-0000-4000-8000-000000000003','admin-domain-staff@example.test');
insert into public.staff_members(user_id,role) values('de000000-0000-4000-8000-000000000002','admin'),('de000000-0000-4000-8000-000000000003','staff');
insert into public.organizations(id,name,slug) values('de000000-0000-4000-8000-000000000011','Admin Domain Fixture','admin-domain-fixture');
insert into public.organization_members(organization_id,user_id,role,status) values('de000000-0000-4000-8000-000000000011','de000000-0000-4000-8000-000000000001','owner','active');
insert into public.projects(id,organization_id,name,kind,status,brief,intake_completed_at) values('de000000-0000-4000-8000-000000000041','de000000-0000-4000-8000-000000000011','Domain reset project','professional','approved','{"basics":{"businessName":"Preserved"},"domain":{"domainId":"de000000-0000-4000-8000-000000000031","hostname":"admin-domain-fixture.com"}}',now());
insert into public.websites(id,organization_id,project_id,name,status) values('de000000-0000-4000-8000-000000000021','de000000-0000-4000-8000-000000000011','de000000-0000-4000-8000-000000000041','Admin domain website','building');
insert into public.domains(id,organization_id,website_id,hostname,source,status,verification) values('de000000-0000-4000-8000-000000000031','de000000-0000-4000-8000-000000000011','de000000-0000-4000-8000-000000000021','admin-domain-fixture.com','customer_owned','pending','{"source":"platform"}');
create temporary table original_token as select verification_token from public.domains where id='de000000-0000-4000-8000-000000000031';
insert into public.provisioning_jobs(organization_id,website_id,domain_id,kind,idempotency_key) values('de000000-0000-4000-8000-000000000011','de000000-0000-4000-8000-000000000021','de000000-0000-4000-8000-000000000031','domain.verify','admin-domain-fixture-verify');
create function admin_domain_test.save(actor uuid default 'de000000-0000-4000-8000-000000000002') returns public.domain_purchase_intents language sql as $$select public.save_domain_handoff('de000000-0000-4000-8000-000000000011','de000000-0000-4000-8000-000000000021',actor,0,'admin-domain-fixture.com','{"hostname":"admin-domain-fixture.com","available":true,"currency":"USD"}',now(),'handoff')$$;
create function admin_domain_test.reset(actor uuid default 'de000000-0000-4000-8000-000000000002',snapshot jsonb default null,version integer default 1,org uuid default 'de000000-0000-4000-8000-000000000011') returns void language sql as $$select public.reset_domain_setup(org,'de000000-0000-4000-8000-000000000021',actor,version,coalesce(snapshot,(select coalesce(jsonb_agg(jsonb_build_object('id',id,'updated_at',updated_at)),'[]') from public.domains where website_id='de000000-0000-4000-8000-000000000021' and status<>'released')))$$;
grant execute on all functions in schema admin_domain_test to authenticated,service_role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select admin_domain_test.fails($q$select admin_domain_test.save('de000000-0000-4000-8000-000000000003')$q$,'ordinary staff cannot manage customer choice');
select admin_domain_test.ok((admin_domain_test.save()).version=1,'administrator saves actual choice without tenant membership');
select admin_domain_test.ok((select count(*)=1 from public.audit_events where action='domain.choice_managed' and actor_user_id='de000000-0000-4000-8000-000000000002'),'staff choice is attributed to real administrator');
select admin_domain_test.fails($q$select admin_domain_test.reset('de000000-0000-4000-8000-000000000001')$q$,'customer cannot reset through administrator RPC');
select admin_domain_test.fails($q$select admin_domain_test.reset('de000000-0000-4000-8000-000000000003')$q$,'ordinary staff cannot reset');
select admin_domain_test.fails($q$select admin_domain_test.reset(snapshot=>'[]')$q$,'incomplete or stale snapshot rejected');
select admin_domain_test.fails($q$select admin_domain_test.reset(snapshot=>'[{"id":"de000000-0000-4000-8000-000000000031","updated_at":"2000-01-01T00:00:00Z"}]')$q$,'changed domain version rejected');
select admin_domain_test.fails($q$select admin_domain_test.reset(version=>0)$q$,'stale choice rejected');
select admin_domain_test.fails($q$select admin_domain_test.reset(org=>'de000000-0000-4000-8000-000000000099')$q$,'website and organization must match');
update public.provisioning_jobs set status='running',locked_by='worker',locked_at=now() where idempotency_key='admin-domain-fixture-verify';
select admin_domain_test.fails($q$select admin_domain_test.reset()$q$,'running worker blocks reset');
update public.provisioning_jobs set status='queued',locked_by=null,locked_at=null where idempotency_key='admin-domain-fixture-verify';
update public.websites set status='live' where id='de000000-0000-4000-8000-000000000021';
select admin_domain_test.fails($q$select admin_domain_test.reset()$q$,'live website cannot reset');
update public.websites set status='building' where id='de000000-0000-4000-8000-000000000021';
update public.domains set verification='{"source":"provider"}' where id='de000000-0000-4000-8000-000000000031';
select admin_domain_test.fails($q$select admin_domain_test.reset()$q$,'provider association cannot reset');
update public.domains set verification='{"source":"platform"}' where id='de000000-0000-4000-8000-000000000031';
insert into public.deployments(organization_id,website_id,environment,status) values('de000000-0000-4000-8000-000000000011','de000000-0000-4000-8000-000000000021','production','ready');
select admin_domain_test.fails($q$select admin_domain_test.reset()$q$,'existing production deployment cannot reset');
delete from public.deployments where website_id='de000000-0000-4000-8000-000000000021';
-- Earlier synthetic live-status checks promoted the fixture project via its
-- lifecycle trigger. Restore its intended prelaunch state before reset.
update public.projects set status='approved' where id='de000000-0000-4000-8000-000000000041';
insert into public.provisioning_jobs(organization_id,website_id,kind,idempotency_key,payload) values('de000000-0000-4000-8000-000000000011','de000000-0000-4000-8000-000000000021','website.deploy','admin-domain-production-queued','{"environment":"production"}');
select admin_domain_test.fails($q$select admin_domain_test.reset()$q$,'queued production launch blocks reset');
delete from public.provisioning_jobs where idempotency_key='admin-domain-production-queued';
update public.domains set status='verifying',dns_ok=true,verification='{"source":"platform","launch_ready":true}' where id='de000000-0000-4000-8000-000000000031';
select admin_domain_test.reset();
select admin_domain_test.ok((select status='released' and dns_ok=false and ssl_ok=false and verification='{}' from public.domains where id='de000000-0000-4000-8000-000000000031'),'reset preserves released history without ownership');
select admin_domain_test.ok((select phase='cancelled' and version=2 from public.domain_purchase_intents where website_id='de000000-0000-4000-8000-000000000021'),'choice cancelled and stale customer tabs invalidated');
select admin_domain_test.ok((select status='canceled' from public.provisioning_jobs where idempotency_key='admin-domain-fixture-verify'),'pending verification work canceled');
select admin_domain_test.ok((select status='canceled' from public.provisioning_jobs where domain_id='de000000-0000-4000-8000-000000000031' and kind='domain.readiness.notify'),'pending readiness email canceled');
select admin_domain_test.ok((select bool_and(read_at is not null) from public.notifications where kind='domain.ready_for_launch' and organization_id='de000000-0000-4000-8000-000000000011'),'old readiness alerts resolved');
select admin_domain_test.ok((select status='building' and live_url is null and primary_domain_id is null from public.websites where id='de000000-0000-4000-8000-000000000021'),'reset does not publish or edit website');
select admin_domain_test.ok((select status='approved' and intake_completed_at is not null and brief='{"basics":{"businessName":"Preserved"}}' from public.projects where id='de000000-0000-4000-8000-000000000041'),'only domain answer clears; approved brief content and intake preserved');
select admin_domain_test.ok((select count(*)=1 from public.audit_events where action='domain.setup_reset' and actor_kind='staff' and actor_user_id='de000000-0000-4000-8000-000000000002'),'reset audited as administrator');
insert into public.domains(organization_id,website_id,hostname,source,status) values('de000000-0000-4000-8000-000000000011','de000000-0000-4000-8000-000000000021','admin-domain-fixture.com','customer_owned','pending');
select admin_domain_test.ok((select count(*)=2 from public.domains where hostname='admin-domain-fixture.com'),'same name can start again with fresh row and proof');
update public.domains set status='verifying',dns_ok=true,verification='{"source":"platform","launch_ready":true}' where hostname='admin-domain-fixture.com' and status='pending';
select admin_domain_test.ok((select count(distinct domain_id)=2 from public.provisioning_jobs where website_id='de000000-0000-4000-8000-000000000021' and kind='domain.readiness.notify'),'new ownership can create its own readiness event after reset');
select admin_domain_test.fails($q$insert into public.domains(organization_id,hostname) values('de000000-0000-4000-8000-000000000011','admin-domain-fixture.com')$q$,'duplicate active domain still blocked');
reset role;
select admin_domain_test.ok((select count(distinct verification_token)=2 and bool_and(verification_token<>(select verification_token from original_token)) from public.domains where hostname='admin-domain-fixture.com'),'old proof invalidated and never reused');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"de000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select admin_domain_test.fails($q$select admin_domain_test.reset()$q$,'even admin browser cannot call service RPC directly');
select admin_domain_test.ok(not has_function_privilege('anon','public.reset_domain_setup(uuid,uuid,uuid,integer,jsonb)','EXECUTE'),'anonymous reset denied');
reset role;
update public.staff_members set role='staff' where user_id='de000000-0000-4000-8000-000000000002';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select admin_domain_test.fails($q$select admin_domain_test.reset()$q$,'revoked admin role checked again in database');
reset role;
rollback;
